#!/usr/bin/env node
'use strict';

// Projects raw project data into per-concern markdown context files.
//
// Usage:
//   node build-project-context.js --project-data <dir> --opencode-dir <dir> \
//        --subdomain unity-3d [--config <context-projections.json>] [--dry-run]
//
// Reads context-projections.json, gathers the referenced source files from the
// project-data directory, and writes one focused markdown file per output under
// <opencode-dir>/<outputDir>/. Missing sources are skipped, never fatal: the
// project data is generated by the plugin in a later step and may be absent.

const fs = require('fs');
const path = require('path');

const MAX_ARRAY_ITEMS = 20;

function parseArgs(argv) {
  const out = {};
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i];
    if (arg.startsWith('--') && arg.includes('=')) {
      const eq = arg.indexOf('=');
      out[arg.slice(2, eq)] = arg.slice(eq + 1);
      i++;
      continue;
    }
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) {
        out[key] = next;
        i += 2;
      } else {
        out[key] = true;
        i++;
      }
      continue;
    }
    i++;
  }
  return out;
}

function isFile(p) {
  try { return fs.statSync(p).isFile(); } catch (_) { return false; }
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

function pick(value, fields) {
  if (!fields || fields.length === 0) return value;
  if (value === null || typeof value !== 'object') return value;
  const out = {};
  for (const f of fields) {
    if (Object.prototype.hasOwnProperty.call(value, f)) out[f] = value[f];
  }
  return out;
}

function truncate(value) {
  if (Array.isArray(value)) {
    if (value.length > MAX_ARRAY_ITEMS) {
      return value.slice(0, MAX_ARRAY_ITEMS).concat([`... (${value.length - MAX_ARRAY_ITEMS} more)`]);
    }
  }
  return value;
}

function renderValue(value) {
  if (typeof value === 'string') return value;
  return '```json\n' + JSON.stringify(truncate(value), null, 2) + '\n```';
}

function collectSection(projectDataDir, source) {
  const file = path.join(projectDataDir, source.file);
  if (!isFile(file)) return null;
  const raw = fs.readFileSync(file, 'utf8');
  let value;
  if (source.file.endsWith('.json')) {
    try {
      value = pick(JSON.parse(raw), source.fields);
    } catch (_) {
      return { heading: source.file, body: '```\n' + raw.trim() + '\n```' };
    }
  } else {
    value = raw.trim();
  }
  return { heading: source.file, body: renderValue(value) };
}

function renderOutput(output, sections) {
  const lines = [];
  lines.push(`<!-- Context: project/${output.file.replace(/\.md$/, '')} | Priority: ${output.priority || 'medium'} | Version: 1.0 | Updated: ${today()} -->`);
  lines.push('');
  lines.push(`# ${output.title}`);
  lines.push('');
  lines.push('> Projected from `.opencode/project-data/`. Do not edit by hand; regenerate instead.');
  lines.push('');
  for (const section of sections) {
    lines.push(`## ${section.heading}`);
    lines.push('');
    lines.push(section.body);
    lines.push('');
  }
  return lines.join('\n');
}

function renderNavigation(config, written) {
  const lines = [];
  lines.push(`<!-- Context: project/navigation | Priority: critical | Version: 1.0 | Updated: ${today()} -->`);
  lines.push('');
  lines.push(`# ${config.subdomain} Project Context`);
  lines.push('');
  lines.push('> Projected from `.opencode/project-data/`. Regenerate with `build-project-context.js`.');
  lines.push('');
  lines.push('| Concern | File | Priority |');
  lines.push('|---------|------|----------|');
  for (const output of config.outputs) {
    const mark = written.includes(output.file) ? '' : ' (not generated)';
    lines.push(`| ${output.title}${mark} | \`${output.file}\` | ${output.priority || 'medium'} |`);
  }
  const consumers = config.consumers || {};
  if (Object.keys(consumers).length > 0) {
    lines.push('');
    lines.push('## Consumers');
    lines.push('');
    for (const [consumer, files] of Object.entries(consumers)) {
      lines.push(`- \`${consumer}\` -> ${files.map((f) => `\`${f}\``).join(', ')}`);
    }
  }
  lines.push('');
  return lines.join('\n');
}

function main() {
  const argv = parseArgs(process.argv.slice(2));
  const projectDataDir = path.resolve(argv['project-data'] || '.opencode/project-data');
  const opencodeDir = path.resolve(argv['opencode-dir'] || '.opencode');
  const configPath = path.resolve(
    argv.config || path.join(__dirname, '..', 'context-projections.json')
  );
  const dryRun = Boolean(argv['dry-run']);

  if (!isFile(configPath)) {
    console.error(`Projection config not found: ${configPath}`);
    process.exit(1);
  }

  const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  const outDir = path.join(opencodeDir, config.outputDir || `context/${config.subdomain}/project`);

  const written = [];
  const skipped = [];

  for (const output of config.outputs || []) {
    const sections = [];
    for (const source of output.sources || []) {
      const section = collectSection(projectDataDir, source);
      if (section) sections.push(section);
    }
    if (sections.length === 0) {
      skipped.push(output.file);
      continue;
    }
    const content = renderOutput(output, sections);
    const dest = path.join(outDir, output.file);
    if (dryRun) {
      console.log(`[dry-run] would write ${path.relative(process.cwd(), dest)}`);
    } else {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, content);
    }
    written.push(output.file);
  }

  if (!dryRun && written.length > 0) {
    fs.writeFileSync(path.join(outDir, 'navigation.md'), renderNavigation(config, written));
  }

  console.log(`Projected ${config.subdomain} project context`);
  console.log(`  Sources:  ${projectDataDir}`);
  console.log(`  Output:   ${path.relative(process.cwd(), outDir)}`);
  console.log(`  Written:  ${written.length}${written.length ? ' (' + written.join(', ') + ')' : ''}`);
  if (skipped.length > 0) {
    console.log(`  Skipped:  ${skipped.length} (no project data yet: ${skipped.join(', ')})`);
  }
}

main();
